import urllib.request,urllib.parse,json,time
from collections import Counter
lines=open('/workspace/pig_mapped_blast.tsv').read().splitlines()
c=Counter()
for line in lines[1:]:
    p=line.split('\\t')
    if len(p)>=12: c[p[1]]+=1
ids=list(c.keys())
print('unique ids',len(ids))
tax_by_acc={}; org_by_acc={}
for i in range(0,len(ids),200):
    batch=ids[i:i+200]
    url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi'
    params={'db':'nuccore','id':','.join(batch),'retmode':'json'}
    for attempt in range(3):
        try:
            req=urllib.request.Request(url+'?'+urllib.parse.urlencode(params),headers={'User-Agent':'Mozilla/5.0'})
            with urllib.request.urlopen(req,timeout=60) as r: data=json.load(r)
            res=data.get('result',{})
            for uid in res.get('uids',[]):
                doc=res[uid]
                acc=doc.get('accessionversion') or doc.get('caption')
                org=doc.get('organism')
                tax=doc.get('taxid')
                tax_by_acc[acc]=tax; org_by_acc[acc]=org
            break
        except Exception as e:
            print('retry',i,e); time.sleep(2)
    time.sleep(0.34)
print('fetched',len(tax_by_acc))
org_count=Counter(); tax_count=Counter(); missing=[]
for acc,n in c.items():
    if acc in org_by_acc:
        org_count[org_by_acc[acc]]+=n; tax_count[tax_by_acc[acc]]+=n
    else: missing.append((acc,n))
print('missing',len(missing),'hits',sum(n for _,n in missing))
print('Top organisms by BLAST hits:')
for org,n in org_count.most_common(40): print(n,org)
print('Top taxids:')
for tax,n in tax_count.most_common(20): print(n,tax)
PY"

